import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import api from '../utils/api';

interface User {
  id: string;
  pseudonym: string;
}

interface Message {
  id: string;
  encryptedContent: string;
  content?: string;
  sentAt: string;
  isAi: boolean;
  sender: User;
}

interface Participant {
  sessionId: string;
  userId: string;
  joinedAt: string;
  user: User;
}

interface Session {
  id: string;
  type: 'individual' | 'joint';
  createdById: string;
  createdAt: string;
  endedAt: string | null;
  participants: Participant[];
  messages: Message[];
}

interface SessionState {
  sessions: Session[];
  currentSession: Session | null;
  loading: boolean;
  error: string | null;
}

const initialState: SessionState = {
  sessions: [],
  currentSession: null,
  loading: false,
  error: null,
};

// Fetch all sessions
export const fetchSessions = createAsyncThunk('sessions/fetchSessions', async (_, { rejectWithValue }) => {
  try {
    const response = await api.get('/sessions');
    return response.data;
  } catch (error: any) {
    return rejectWithValue(error.response?.data?.message || 'Failed to fetch sessions');
  }
});

// Fetch a single session
export const fetchSession = createAsyncThunk(
  'sessions/fetchSession',
  async (sessionId: string, { rejectWithValue }) => {
    try {
      const response = await api.get(`/sessions/${sessionId}`);
      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to fetch session');
    }
  }
);

// Create a new session
export const createSession = createAsyncThunk(
  'sessions/createSession',
  async (
    { type, participantIds }: { type: 'individual' | 'joint'; participantIds?: string[] },
    { rejectWithValue }
  ) => {
    try {
      const response = await api.post('/sessions', { type, participantIds });
      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to create session');
    }
  }
);

// End a session
export const endSession = createAsyncThunk(
  'sessions/endSession',
  async (sessionId: string, { rejectWithValue }) => {
    try {
      const response = await api.put(`/sessions/${sessionId}/end`);
      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to end session');
    }
  }
);

const sessionSlice = createSlice({
  name: 'sessions',
  initialState,
  reducers: {
    clearSessionError: (state) => {
      state.error = null;
    },
    clearCurrentSession: (state) => {
      state.currentSession = null;
    },
    addMessageToCurrentSession: (state, action: PayloadAction<Message>) => {
      if (state.currentSession) {
        state.currentSession.messages.push(action.payload);
      }
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch sessions
      .addCase(fetchSessions.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchSessions.fulfilled, (state, action: PayloadAction<Session[]>) => {
        state.sessions = action.payload;
        state.loading = false;
      })
      .addCase(fetchSessions.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Fetch single session
      .addCase(fetchSession.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchSession.fulfilled, (state, action: PayloadAction<Session>) => {
        state.currentSession = action.payload;
        state.loading = false;
      })
      .addCase(fetchSession.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Create session
      .addCase(createSession.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(createSession.fulfilled, (state, action: PayloadAction<Session>) => {
        state.sessions = [action.payload, ...state.sessions];
        state.currentSession = action.payload;
        state.loading = false;
      })
      .addCase(createSession.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // End session
      .addCase(endSession.fulfilled, (state, action: PayloadAction<Session>) => {
        const index = state.sessions.findIndex((session) => session.id === action.payload.id);
        if (index !== -1) {
          state.sessions[index] = action.payload;
        }
        if (state.currentSession && state.currentSession.id === action.payload.id) {
          state.currentSession = action.payload;
        }
      });
  },
});

export const { clearSessionError, clearCurrentSession, addMessageToCurrentSession } = sessionSlice.actions;
export default sessionSlice.reducer;
